# -*- coding: utf-8 -*-
"""Create a truth-labelled baseline vs optimized evaluation summary."""
from __future__ import print_function, unicode_literals
import json, os, sys, time
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.pardir))
R = os.path.join(ROOT, "harness", "reports")
D = os.path.join(ROOT, "harness", "datasets")
OUTJ = os.path.join(R, "ecommerce_optimized_evaluation_report.json")
OUTM = os.path.join(R, "ecommerce_optimized_evaluation_report.md")

def read(path):
    with open(path, "r", encoding="utf-8") as h: return json.load(h)
def count(name): return sum(1 for l in open(os.path.join(D,name), "r", encoding="utf-8") if l.strip())
def main():
    manifest=read(os.path.join(D,"DATASET_MANIFEST_v2.json")); quality=read(os.path.join(R,"ecommerce_dataset_quality_report_v2.json")); val=read(os.path.join(R,"ecommerce_dataset_validation_report_v2.json")); gate=read(os.path.join(R,"v2_dataset_contract_gate_report.json")); sql=read(os.path.join(R,"ecommerce_sql_fixture_gold_v2_report.json")); rag=read(os.path.join(R,"rag_threshold_eval_report.json")); diag=read(os.path.join(R,"ecommerce_agent_diagnosis_55_latest.json")); e2e=read(os.path.join(R,"e2e_sql_eval_report.json"))
    previous_rag=0.294 # Earlier recorded runner interpretation, only comparable directionally; it mixed retrieval with answerability.
    selected=rag.get("selected_threshold_by_rule",{})
    total=sum(x["record_count"] for x in manifest["datasets"].values())
    report={"contract":"ecommerce_optimized_evaluation_summary_v1","generated_at":time.strftime("%Y-%m-%dT%H:%M:%S%z"),"scope":"offline deterministic evaluation-data optimization and reproducible local runners","dataset_v2":{"total_records":total,"manifest":"harness/datasets/DATASET_MANIFEST_v2.json","validation_passed":val.get("passed"),"datasets":manifest.get("datasets"),"quality":quality.get("datasets")},"measured_results":{"v2_dataset_contract_gate":gate,"v2_sql_fixture_measurement":sql,"current_e2e_sql_58":e2e.get("metrics"),"current_rag_threshold": {"dataset":rag.get("dataset"),"metrics":selected,"confidence_intervals_95":rag.get("confidence_intervals_95"),"metric_semantics":rag.get("manifest",{}).get("metric_semantics")},"diagnosis_existing_baseline":{"case_count":diag.get("metrics",{}).get("total"),"pass_rate":diag.get("metrics",{}).get("pass_rate"),"critical_hallucination_count":diag.get("metrics",{}).get("quality",{}).get("critical_hallucination_count"),"average_score":diag.get("metrics",{}).get("quality",{}).get("average_score")}},"baseline_vs_optimized":{"data_records":{"baseline":942,"optimized":total,"delta":total-942,"comparable":True},"rag_recall_at_5":{"baseline":previous_rag,"optimized":selected.get("recall@5"),"comparable":False,"reason":"optimized runner separates candidate retrieval from answerability and corrects auto-sampled gold equivalence; do not represent as a model-performance gain."},"rag_safety":{"optimized_no_answer_recall":selected.get("no_answer_recall"),"optimized_false_answer_rate":selected.get("false_answer_rate"),"optimized_citation_accuracy":selected.get("citation_accuracy"),"comparable":True},"sql_fixture":{"baseline":"result shape only (58 cases)","optimized":"182 deterministic result checksums / 200 v2 candidates","comparable":False,"reason":"measurement coverage increased and has separate negative-policy metric."},"diagnosis":{"baseline_critical_hallucination_count":31,"optimized":"not improved in this change; retained as an explicit open risk","comparable":True}},"known_open_risks":["Diagnosis harness remains 55/55 terminal-status pass but records 31 critical hallucination-risk observations; do not claim hallucination-free diagnosis.","RAG Recall@5 remains low (0.30 on revised 20-positive auto-sampled set); local deterministic embeddings and auto-generated cases are not production retrieval evidence.","Most v2 labels are synthetic structured candidates pending human adjudication; label provenance is intentionally carried in every record.","SQL v2 has 3 negative clarification mismatches (negative-policy intent rate 0.8333).","v2 contract gate validates fail-closed contracts and label integrity, not all 2,050 cases against live AgentFacade."],"safe_resume_claims":["Built a versioned 2,050-record ecommerce evaluation-data suite with schema validation, provenance, adversarial coverage, and manifest hashes.","Measured 182 executable SQLite fixture cases with reproducible SQL/result checksums; overall v2 fixture case pass rate was 0.985, with 3 recorded clarification mismatches.","The evidence/safety/resilience dataset contract gate passed at 1.0 for its declared offline contract checks.","RAG runner now reports retrieval candidate recall separately from answerability/abstention, preventing a threshold gate from being mislabeled as retrieval recall."]}
    with open(OUTJ,"w",encoding="utf-8") as h: json.dump(report,h,ensure_ascii=False,indent=2,sort_keys=True)
    md="# Ecommerce Evaluation Optimization Report\n\n## Scope\nOffline, deterministic evaluation-data and runner optimization. It is **not** a production benchmark.\n\n## Dataset v2\n- **%d records** across E2E, SQL, RAG, safety, evidence, multi-turn, resilience and tool-routing suites.\n- Validation: **%s**. Every record carries v2 contract and provenance fields; most remain pending human adjudication.\n\n## Measured results\n- V2 evidence/safety/resilience contract gate: evidence 1.0, safety label integrity 1.0, resilience idempotency label integrity 1.0.\n- SQL fixture: **182/182** positive candidates executed with deterministic checksums; total **197/200 (0.985)**, negative policy intent **0.8333** (3 clarification mismatches retained).\n- Existing 58-case SQL runner: 1.0 overall pass, local rule-based parser/compiler + SQLite only.\n- RAG revised runner: Recall@5 **%.4f**, Recall@10 **%.4f**, no-answer recall **%.4f**, false-answer rate **%.4f**, citation accuracy **%.4f**. Revised metric semantics make prior 0.294 Recall@5 non-comparable.\n\n## Explicit open risks\n- Diagnosis baseline still has **31** critical hallucination-risk observations. No claim of improvement was made.\n- RAG local deterministic result is weak and is not a production retrieval claim.\n- No real external traffic, provider cost, production database, or human-gold accuracy is measured.\n" % (total, val.get("passed"), selected.get("recall@5",0), selected.get("recall@10",0), selected.get("no_answer_recall",0), selected.get("false_answer_rate",0), selected.get("citation_accuracy",0))
    with open(OUTM,"w",encoding="utf-8") as h:h.write(md)
    print(json.dumps({"report":OUTJ,"markdown":OUTM,"total_records":total},ensure_ascii=False)); return 0
if __name__=="__main__":sys.exit(main())
